//! Differential tests for `archava-capacity`.
//!
//! Every expected value below was produced by running the baseline's own
//! `calculateSchedule` over a fixed fixture set — see
//! `rust/crates/capacity/tests/reference.json`, generated by
//! `tools/rust/capacity-probe.mjs`. Nothing here is a value this port's author
//! derived by reading the TypeScript and reasoning about it.
//!
//! That matters more here than anywhere else in the workspace, because
//! `calculateSchedule` is **tested nowhere in the product**. The only test file
//! in either capacity package (`packages/capacity/test/boundaries.test.ts`)
//! exercises `CapacityService` against a stub repository whose `estimate`
//! returns a hard-coded object, so the real function never runs. A port checked
//! by reading the code would therefore be a port checked against nothing at
//! all; the probe exists so there is a first-hand record of what TypeScript
//! actually returned, and this file is what holds the port to it.
//!
//! ## The three cases that caught real mistakes
//!
//! * `offset-tz-negative` — the desired start is `2030-01-07T00:00:00-05:00`,
//!   which is `05:00` UTC on a Monday. `nextBusinessDay` is a **no-op on a
//!   weekday**, so the time-of-day survives into the result. A port that zeroed
//!   the time on every `nextBusinessDay` call — because the baseline's
//!   `setUTCHours(0, 0, 0, 0)` is right there in the loop — would produce
//!   `00:00` and be wrong by five hours.
//! * `two-sequential-allocations` — the queue position is 2, not 1. Two
//!   allocations are already running, so the rule that counts allocations whose
//!   finish is past the desired time counts both, and the floor of 1 is not
//!   what is being exercised.
//! * `epsilon-admits-one-ulp-over-capacity` — the `+1e-6` tolerance at
//!   `repository.ts:189` is load-bearing. `weeklyCapacity: 3` plus a 1-unit
//!   allocation over 5 working days plus a 0.8-unit job: in exact arithmetic
//!   `0.2 + 0.4 == 0.6` is a *fit*, but in `f64` it is `0.6000000000000001`,
//!   one ULP over, and the tolerance is what admits Monday. Its control
//!   (`epsilon-does-not-admit-a-real-overrun`) pins that a real 40-unit overrun
//!   is still refused, so the tolerance is a tolerance and not a pass-through.
//!
//! ## The wall-clock case, and why it is not compared
//!
//! `no-desired-start` records `desired: null`, so the baseline read
//! `new Date()`. Its recorded timestamps are therefore the moment the probe
//! ran, and they move on every regeneration — the file is deliberately not
//! byte-reproducible for that one case. Rather than paper over it with a
//! tolerance, `the_wall_clock_case_is_recorded_and_not_faked` splits it: the
//! fields that do not depend on the clock are compared exactly, the recorded
//! start is checked to be a weekday (which is what proves the baseline applied
//! `nextBusinessDay` to `now`), and the port's own no-desired path is exercised
//! by feeding the recorded instant back in, where it *is* comparable.

use archava_capacity::schedule::{
    calculate_schedule, ActiveAllocation, PoolCapacity, ScheduleResult, CAPACITY_EPSILON,
    MAX_ITERATIONS,
};
use archava_capacity::{count_working_days, next_business_day, CapacityError, Instant, MS_PER_DAY};
use serde::Deserialize;

/// The reference file's own header, deserialized so a regenerated file with a
/// rewritten shape fails here rather than silently comparing zero cases.
#[derive(Debug, Deserialize)]
struct Reference {
    slice: String,
    count: usize,
    cases: Vec<Case>,
}

/// One recorded case.
///
/// The field names are the PostgreSQL row spelling the probe emitted —
/// `weeklyCapacity`, `scheduledStartAt` and the rest — and they stay that way
/// rather than being renamed to Rust's convention, because this struct's whole
/// job is to be a faithful description of what the baseline wrote. The names
/// are also the assertion: if the reference file's spelling ever changes, this
/// stops compiling instead of reading `None` out of every field.
#[derive(Debug, Deserialize)]
struct Case {
    name: String,
    pool: RowPool,
    allocs: Vec<RowAlloc>,
    units: f64,
    desired: Option<String>,
    ok: Option<RowResult>,
    err: Option<String>,
}

/// The pool row as the baseline spells it.
#[derive(Debug, Deserialize)]
struct RowPool {
    #[serde(rename = "weeklyCapacity")]
    weekly_capacity: f64,
    #[serde(rename = "maxConcurrentJobs")]
    max_concurrent_jobs: u32,
}

/// One allocation row, carrying only the four columns the baseline's
/// `allocDetails` projection reads plus the `id` it carries and ignores.
#[derive(Debug, Deserialize)]
struct RowAlloc {
    id: String,
    #[serde(rename = "scheduledStartAt")]
    scheduled_start_at: String,
    #[serde(rename = "scheduledFinishAt")]
    scheduled_finish_at: String,
    #[serde(rename = "requiredUnits")]
    required_units: f64,
    #[serde(rename = "remainingUnits")]
    remaining_units: f64,
}

/// What the baseline returned, in its own spelling.
#[derive(Debug, Deserialize)]
struct RowResult {
    #[serde(rename = "queuePosition")]
    queue_position: u32,
    #[serde(rename = "scheduledStartAt")]
    scheduled_start_at: String,
    #[serde(rename = "scheduledFinishAt")]
    scheduled_finish_at: String,
    #[serde(rename = "burnRatePerDay")]
    burn_rate_per_day: f64,
    #[serde(rename = "estimatedCalendarDays")]
    estimated_calendar_days: u32,
    #[serde(rename = "workingDays")]
    working_days: u32,
}

/// The parsed reference file.
fn reference() -> Reference {
    let text = include_str!("reference.json");
    serde_json::from_str(text).expect("reference.json matches the schema this test reads")
}

/// Row → the port's own input type.
///
/// A total conversion by construction: the reference file's pool is exactly a
/// weekly capacity and a concurrency limit, and its allocation is exactly an id
/// and four fields. If the crate's input type ever gains a field, this function
/// stops compiling rather than defaulting it.
fn pool_of(row: &RowPool) -> PoolCapacity {
    PoolCapacity {
        weekly_capacity: row.weekly_capacity,
        max_concurrent_jobs: row.max_concurrent_jobs,
    }
}

/// Row → the port's own allocation type, with both timestamps parsed by the
/// same ISO reader the desired start uses.
fn alloc_of(row: &RowAlloc) -> ActiveAllocation {
    ActiveAllocation {
        id: row.id.clone(),
        start: instant_from_iso(&row.scheduled_start_at),
        finish: instant_from_iso(&row.scheduled_finish_at),
        required_units: row.required_units,
        remaining_units: row.remaining_units,
    }
}

/// Milliseconds for `days` days after the epoch, matching the baseline's own
/// `+ 24 * 60 * 60 * 1000` arithmetic.
fn days(days: i64) -> i64 {
    days * MS_PER_DAY
}

/// Day number of a UTC date, so the weekday constants below are *derived* from
/// the same civil calendar the ISO reader uses rather than typed by hand.
///
/// The first draft of this file spelled `21_930` for "2030-01-07" and was wrong
/// by nine days — 21930 is a Wednesday, which made `count_working_days` return
/// 3 where the fixture needed 4 and sent a morning looking for an arithmetic
/// bug that was a typo. Deriving the number costs nothing and makes the mistake
/// unrepresentable.
fn day_of(year: i64, month: u32, day: u32) -> i64 {
    days_from_civil(year, month, day)
}

/// Parse an ISO-8601 instant into the millisecond count JavaScript's `Date`
/// constructor would have produced for the same string.
///
/// Hand-rolled, and deliberately narrow: the three forms the fixture set
/// contains are a trailing `Z`, a `+hh:mm` offset and a `-hh:mm` offset, with
/// the fractional seconds either present (`.500`) or absent. A form outside
/// that set panics, because reaching one means the reference file changed shape
/// and the honest response is to look at it — not to guess at a rule the
/// baseline's own `Date` parser applies and this function does not.
///
/// This is also the whole reason the crate carries no date crate: without this
/// function the reference file's strings could not become integers at all.
fn instant_from_iso(text: &str) -> Instant {
    let (date, rest) = text
        .split_once('T')
        .expect("an ISO instant has a date and a time");
    let year: i64 = slice(date, 0, 4).parse().expect("a four-digit year");
    let month: u32 = slice(date, 5, 7).parse().expect("a two-digit month");
    let day: u32 = slice(date, 8, 10).parse().expect("a two-digit day");
    let hour: i64 = slice(rest, 0, 2).parse().expect("a two-digit hour");
    let minute: i64 = slice(rest, 3, 5).parse().expect("a two-digit minute");

    // Everything after the minute is seconds, an optional fraction, and an
    // optional offset — in either order in principle, so split on the offset
    // first and parse the clock from what is left of it.
    let tail = &rest[6..];
    let (clock, offset_minutes) = match tail.strip_suffix('Z') {
        Some(clock) => (clock, 0),
        None => {
            let at = tail
                .rfind(['+', '-'])
                .expect("a non-Z instant carries a +hh:mm or -hh:mm offset");
            let offset = &tail[at + 1..];
            let (offset_hours, offset_minutes) =
                offset.split_once(':').expect("an offset is hh:mm");
            let hours: i64 = offset_hours.parse().expect("two offset hour digits");
            let minutes: i64 = offset_minutes.parse().expect("two offset minute digits");
            let sign = if &tail[at..at + 1] == "+" { 1 } else { -1 };
            (slice_of(tail, 0, at), sign * (hours * 60 + minutes))
        }
    };

    let (second, millis): (i64, i64) = match clock.split_once('.') {
        Some((second, fraction)) => (
            second.parse().expect("two second digits"),
            fraction_to_millis(fraction),
        ),
        None => (clock.parse().expect("a second count"), 0),
    };

    let day_millis = days_from_civil(year, month, day) * MS_PER_DAY;
    let time_millis = (hour * 3_600 + minute * 60 + second) * 1_000 + millis;
    // A positive offset means local time is ahead of UTC, so UTC is earlier.
    Instant::from_millis(day_millis + time_millis - offset_minutes * 60_000)
}

/// `text[from..to]`, as a `&str`.
fn slice(text: &str, from: usize, to: usize) -> &str {
    text.get(from..to).expect("an ASCII digit range")
}

/// `text[from..to]` where the bounds come from a byte scan.
fn slice_of(text: &str, from: usize, to: usize) -> &str {
    slice(text, from, to)
}

/// `.500` is 500 milliseconds and `.5` is also 500.
///
/// Truncated rather than rounded after the third digit, matching `Date`, which
/// reads exactly three fractional digits and ignores the rest.
fn fraction_to_millis(fraction: &str) -> i64 {
    let mut padded = String::from(fraction);
    while padded.len() < 3 {
        padded.push('0');
    }
    padded.truncate(3);
    padded.parse().expect("fractional digits")
}

/// Days since 1970-01-01 for a proleptic-Gregorian date.
///
/// Howard Hinnant's `days_from_civil`, used in both directions here: the
/// reference file's ISO strings have to become the port's millisecond counts,
/// and the port's millisecond counts have to become ISO strings again so they
/// can be compared to what the baseline recorded. It is not a dependency
/// because it is arithmetic, not a calendar library — no timezone, no locale,
/// no DST, which is precisely the surface this crate refuses to take on.
fn days_from_civil(year: i64, month: u32, day: u32) -> i64 {
    let month = i64::from(month);
    let day = i64::from(day);
    let shifted = year - i64::from(month <= 2);
    let era = shifted.div_euclid(400);
    let year_of_era = shifted.rem_euclid(400);
    let month_position = month + 9 - 12 * i64::from(month > 2);
    let day_of_year = (153 * month_position + 2) / 5 + day - 1;
    let day_of_era = year_of_era * 365 + year_of_era / 4 - year_of_era / 100 + day_of_year;
    era * 146_097 + day_of_era - 719_468
}

/// The inverse of [`days_from_civil`].
fn civil_from_days(days: i64) -> (i64, u32, u32) {
    let shifted = days + 719_468;
    let era = shifted.div_euclid(146_097);
    let day_of_era = shifted.rem_euclid(146_097);
    let year_of_era =
        (day_of_era - day_of_era / 1_460 + day_of_era / 36_524 - day_of_era / 146_096) / 365;
    let year = year_of_era + era * 400;
    let day_of_year = day_of_era - (365 * year_of_era + year_of_era / 4 - year_of_era / 100);
    let month_position = (5 * day_of_year + 2) / 153;
    let day = (day_of_year - (153 * month_position + 2) / 5 + 1) as u32;
    let month = if month_position < 10 {
        month_position + 3
    } else {
        month_position - 9
    } as u32;
    (year + i64::from(month <= 2), month, day)
}

/// Render an instant the way the baseline's `toISOString()` does: UTC, always
/// three fractional digits, trailing `Z`.
fn instant_to_iso(instant: Instant) -> String {
    let total = instant.as_millis();
    let day_millis = total.rem_euclid(MS_PER_DAY);
    let (year, month, day) = civil_from_days(total.div_euclid(MS_PER_DAY));
    format!(
        "{year:04}-{month:02}-{day:02}T{:02}:{:02}:{:02}.{:03}Z",
        day_millis / 3_600_000,
        (day_millis / 60_000) % 60,
        (day_millis / 1_000) % 60,
        day_millis % 1_000,
    )
}

/// Field-by-field comparison of a recorded result against a computed one.
///
/// The burn rate is compared by `to_bits()` rather than by `==`, so a `-0.0`
/// against a `0.0` or a `NaN` against a `NaN` surfaces as the difference it is.
/// `PartialEq` on `f64` would call both of those equal, and an equality that
/// cannot distinguish `NaN` from `NaN` is not an equality worth asserting a
/// ported arithmetic result with.
fn assert_matches(name: &str, recorded: &RowResult, actual: ScheduleResult) {
    assert_eq!(
        actual.queue_position, recorded.queue_position,
        "{name}: queuePosition"
    );
    assert_eq!(
        instant_to_iso(actual.scheduled_start),
        recorded.scheduled_start_at,
        "{name}: scheduledStartAt"
    );
    assert_eq!(
        instant_to_iso(actual.scheduled_finish),
        recorded.scheduled_finish_at,
        "{name}: scheduledFinishAt"
    );
    assert_eq!(
        actual.burn_rate_per_day.to_bits(),
        recorded.burn_rate_per_day.to_bits(),
        "{name}: burnRatePerDay"
    );
    assert_eq!(
        actual.estimated_calendar_days, recorded.estimated_calendar_days,
        "{name}: estimatedCalendarDays"
    );
    assert_eq!(
        actual.working_days, recorded.working_days,
        "{name}: workingDays"
    );
}

/// The suite itself: every recorded case, run through the port and compared
/// field by field.
///
/// One loop rather than thirty-seven near-identical tests, because a failure
/// here should name the case that diverged and nothing else. `panic` inside a
/// `#[test]` body stops at the first divergence, which is the behaviour wanted:
/// the case name is in every message, so the report is
/// `epsilon-admits-one-ulp-over-capacity: scheduledStartAt` rather than a mass
/// assertion dump.
#[test]
fn reproduces_every_recorded_baseline_result() {
    let reference = reference();
    let mut scheduled = 0usize;
    let mut refused = 0usize;
    let mut wall_clock = 0usize;

    for case in &reference.cases {
        let desired = case.desired.as_deref().map(instant_from_iso);
        let allocations: Vec<ActiveAllocation> = case.allocs.iter().map(alloc_of).collect();
        let computed = calculate_schedule(pool_of(&case.pool), &allocations, case.units, desired);

        match (&case.ok, &case.err, computed) {
            // The wall-clock case is compared by its own test, not here: its
            // recorded timestamps move on every regeneration, so comparing it
            // in the loop would throw for a reason that is not a divergence.
            (Some(_), None, Ok(_)) if case.desired.is_none() => {
                wall_clock += 1;
            }
            (Some(recorded), None, Ok(actual)) => {
                assert_matches(&case.name, recorded, actual);
                scheduled += 1;
            }
            (None, Some(code), Err(error)) => {
                assert_eq!(
                    error.code(),
                    code,
                    "{}: the baseline refused with a different code",
                    case.name
                );
                refused += 1;
            }
            (Some(_), None, Err(error)) => {
                panic!(
                    "{}: the baseline scheduled this and the port refused it ({})",
                    case.name,
                    error.code()
                );
            }
            (None, Some(_), Ok(actual)) => {
                panic!(
                    "{}: the baseline refused this and the port scheduled it \
                     (start {})",
                    case.name,
                    instant_to_iso(actual.scheduled_start)
                );
            }
            (None, None, _) => {
                panic!(
                    "{}: the reference records neither a result nor an error",
                    case.name
                );
            }
            (Some(_), Some(_), _) => {
                panic!(
                    "{}: the reference records both a result and an error",
                    case.name
                );
            }
        }
    }

    // The denominators, asserted so a run's output states what it covered rather
    // than leaving a reader to trust the loop above did what it says. Each is a
    // literal rather than a sum of the others, because "the loop ran N times" is
    // exactly what would go unnoticed if the loop silently stopped iterating.
    assert_eq!(scheduled, 33, "scheduled cases compared");
    assert_eq!(refused, 3, "refused cases compared");
    assert_eq!(wall_clock, 1, "wall-clock cases deferred to their own test");
    assert_eq!(scheduled + refused + wall_clock, reference.count);
}

/// The wall-clock case, split into the part that is comparable and the part
/// that is not, with the reason recorded rather than tolerance'd away.
#[test]
fn the_wall_clock_case_is_recorded_and_not_faked() {
    let reference = reference();
    let case = reference
        .cases
        .iter()
        .find(|case| case.name == "no-desired-start")
        .expect("the wall-clock fixture is present");
    let recorded = case
        .ok
        .as_ref()
        .expect("the baseline scheduled it rather than refusing");

    // The desired start is `null` — this is the only case in the set that is,
    // and it is what makes the baseline read `new Date()`.
    assert_eq!(case.desired, None, "the case records no desired start");

    // Everything that does not depend on *when* the probe ran.
    assert_eq!(recorded.queue_position, 0);
    assert_eq!(recorded.burn_rate_per_day.to_bits(), 40.0_f64.to_bits());
    assert_eq!(recorded.estimated_calendar_days, 1);
    assert_eq!(recorded.working_days, 1);

    let start = instant_from_iso(&recorded.scheduled_start_at);

    // The recorded start is a weekday. That is the observable trace of the
    // baseline having pushed `new Date()` through `nextBusinessDay`: had it not,
    // a probe run on a Saturday or Sunday would have recorded a weekend start.
    assert!(
        !start.is_weekend(),
        "the baseline moved `now` to a business day: {}",
        instant_to_iso(start)
    );

    // The finish is exactly one day later, which is the `+ 24 * 60 * 60 * 1000`
    // step applied to a job that needs a single working day.
    let finish = instant_from_iso(&recorded.scheduled_finish_at);
    assert_eq!(finish.as_millis() - start.as_millis(), MS_PER_DAY);

    // And now the port's *arithmetic* is comparable after all: feed the
    // recorded instant back as an explicit desired start. `nextBusinessDay` is a
    // no-op on a weekday, so this is the same day the loop would have begun
    // from, and every recorded field should reproduce.
    let actual = calculate_schedule(pool_of(&case.pool), &[], case.units, Some(start))
        .expect("an idle pool schedules this");
    assert_matches(
        "no-desired-start (clock replayed as a desired start)",
        recorded,
        actual,
    );
}

/// The fixture set is load-bearing evidence, so its shape is asserted rather
/// than assumed.
///
/// If a case is ever deleted, the suite fails here instead of quietly comparing
/// thirty-six. The names listed are the ones whose doc comments explain a rule
/// a reader would otherwise have no reason to look for.
#[test]
fn the_fixture_set_is_intact() {
    let reference = reference();
    assert_eq!(reference.slice, "p3", "the slice this reference covers");
    assert_eq!(
        reference.count,
        reference.cases.len(),
        "count matches the case list"
    );

    let names: Vec<&str> = reference
        .cases
        .iter()
        .map(|case| case.name.as_str())
        .collect();
    for must_keep in [
        "offset-tz-negative",
        "offset-tz-desired",
        "offset-tz-desired-no-frac",
        "no-milliseconds",
        "timestamp-with-time-of-day",
        "two-sequential-allocations",
        "epsilon-admits-one-ulp-over-capacity",
        "epsilon-does-not-admit-a-real-overrun",
        "unsatisfiable-concurrency",
        "permanent-saturation",
        "burn-rate-zero-refuses",
        "burn-rate-negative-refuses",
        "zero-length-allocation-burns-one-day",
        "no-desired-start",
    ] {
        assert!(
            names.contains(&must_keep),
            "{must_keep} is still in the fixture set"
        );
    }

    // Exactly one case reads the wall clock, and it is named here rather than
    // discovered by running the suite twice and diffing.
    assert_eq!(
        names
            .iter()
            .filter(|name| **name == "no-desired-start")
            .count(),
        1
    );
}

/// The two literals the port carries are the baseline's literals, not
/// hand-chosen equivalents.
///
/// `1e-6` is the capacity tolerance at `repository.ts:189` and `1000` is the
/// loop bound at `repository.ts:153`. Both are easy to "clean up" — an epsilon
/// looks like a magic number and a round loop bound looks arbitrary — so they
/// are pinned to the values the baseline spells.
#[test]
fn the_two_literals_are_the_baselines_literals() {
    assert_eq!(CAPACITY_EPSILON.to_bits(), 1e-6_f64.to_bits());
    assert_eq!(MAX_ITERATIONS, 1000);
}

/// The day step is the baseline's own `24 * 60 * 60 * 1000`.
///
/// Asserted as arithmetic rather than as a literal so that editing the
/// expression cannot drift from editing the constant's value.
#[test]
fn the_day_step_is_the_baselines_day_step() {
    assert_eq!(MS_PER_DAY, 24 * 60 * 60 * 1000);
    assert_eq!(days(1), 86_400_000);
    assert_eq!(days(-1), -86_400_000);
}

/// The reference file's rows are the port's inputs, spelled the way PostgreSQL
/// spells them.
///
/// This is the test that keeps the differential suite honest about its own
/// plumbing. The conversion from a row to `PoolCapacity`/`ActiveAllocation` is
/// the one place a field could be silently dropped or mis-mapped, and every
/// other assertion in this file would then be comparing the wrong input.
#[test]
fn the_reference_rows_deserialize_into_the_ports_inputs() {
    let reference = reference();
    let case = reference
        .cases
        .iter()
        .find(|case| case.name == "two-sequential-allocations")
        .expect("the multi-allocation fixture is present");

    let pool = pool_of(&case.pool);
    assert_eq!(pool.weekly_capacity, 200.0);
    assert_eq!(pool.max_concurrent_jobs, 1);

    let allocations: Vec<ActiveAllocation> = case.allocs.iter().map(alloc_of).collect();
    assert_eq!(allocations.len(), 2);

    // Both timestamps land where the ISO strings put them: 2030-01-07 and
    // 2030-01-09 UTC, and again for 2030-01-09 and 2030-01-11.
    assert_eq!(allocations[0].start.as_millis(), days(day_of(2030, 1, 7)));
    assert_eq!(allocations[0].finish.as_millis(), days(day_of(2030, 1, 9)));
    assert_eq!(allocations[0].required_units, 80.0);
    assert_eq!(allocations[0].remaining_units, 80.0);
    assert_eq!(allocations[0].id, "a1");

    assert_eq!(allocations[1].start.as_millis(), days(day_of(2030, 1, 9)));
    assert_eq!(allocations[1].finish.as_millis(), days(day_of(2030, 1, 11)));
    assert_eq!(allocations[1].id, "a2");
}

/// A pool that cannot burn anything per day is refused before the search.
///
/// `repository.ts:124` throws on `dailyBurnRate <= 0`, which is the only
/// refusal reached without building the allocation projection. Two cases pin
/// it: `0` is the boundary itself, and `-50` reaches the same branch through
/// the negative half. Neither is a schema-legal row — `capacityPoolSchema`
/// declares `weeklyCapacity: z.number().positive()` — and both are recorded
/// anyway, because the baseline validates nothing and a caller can hand the
/// function whatever it computed.
#[test]
fn a_pool_that_cannot_burn_is_refused_before_the_search() {
    for weekly in [0.0, -50.0] {
        let error = calculate_schedule(
            PoolCapacity {
                weekly_capacity: weekly,
                max_concurrent_jobs: 5,
            },
            &[],
            40.0,
            Some(Instant::from_millis(days(day_of(2030, 1, 7)))),
        )
        .expect_err("a pool with no daily burn cannot schedule anything");

        assert_eq!(error, CapacityError::insufficient_capacity());
        assert_eq!(error.code(), "insufficient_capacity");
    }
}

/// Non-finite input is refused at the entry before any arithmetic runs.
///
/// NaN and Infinity are not schema-legal, but nothing inside `calculateSchedule`
/// checks them, so they would otherwise flow straight into `workingDaysNeeded`
/// and burn the 1000-iteration loop without making progress.
#[test]
fn non_finite_input_is_refused_at_entry() {
    let monday = Instant::from_millis(days(day_of(2030, 1, 7)));

    // NaN weekly capacity
    let error = calculate_schedule(
        PoolCapacity {
            weekly_capacity: f64::NAN,
            max_concurrent_jobs: 5,
        },
        &[],
        40.0,
        Some(monday),
    )
    .expect_err("NaN weekly capacity is invalid");
    assert_eq!(error, CapacityError::invalid_request());
    assert_eq!(error.code(), "invalid_request");

    // Infinity weekly capacity
    let error = calculate_schedule(
        PoolCapacity {
            weekly_capacity: f64::INFINITY,
            max_concurrent_jobs: 5,
        },
        &[],
        40.0,
        Some(monday),
    )
    .expect_err("Infinity weekly capacity is invalid");
    assert_eq!(error, CapacityError::invalid_request());
    assert_eq!(error.code(), "invalid_request");

    // NaN required units
    let error = calculate_schedule(
        PoolCapacity {
            weekly_capacity: 200.0,
            max_concurrent_jobs: 5,
        },
        &[],
        f64::NAN,
        Some(monday),
    )
    .expect_err("NaN required units is invalid");
    assert_eq!(error, CapacityError::invalid_request());
    assert_eq!(error.code(), "invalid_request");

    // Infinity required units
    let error = calculate_schedule(
        PoolCapacity {
            weekly_capacity: 200.0,
            max_concurrent_jobs: 5,
        },
        &[],
        f64::INFINITY,
        Some(monday),
    )
    .expect_err("Infinity required units is invalid");
    assert_eq!(error, CapacityError::invalid_request());
    assert_eq!(error.code(), "invalid_request");
}

/// A zero-length allocation span counts as one working day.
///
/// `countWorkingDays` floors to 1 at `repository.ts:105`. Without that floor the
/// per-allocation daily rate divides by zero and yields `Infinity`, which then
/// makes every following day read as over capacity — so the fixture is the
/// difference between "this allocation burns a day" and "this allocation poisons
/// the schedule".
#[test]
fn a_zero_length_allocation_burns_one_day() {
    let monday = Instant::from_millis(days(day_of(2030, 1, 7)));
    assert_eq!(count_working_days(monday, monday).expect("in-domain"), 1);

    // And it schedules, rather than poisoning the day it runs on: a weekend
    // start still skips to Monday and the job finishes the next day.
    let actual = calculate_schedule(
        PoolCapacity {
            weekly_capacity: 200.0,
            max_concurrent_jobs: 1,
        },
        &[ActiveAllocation {
            id: "instant".to_string(),
            start: monday,
            finish: monday,
            required_units: 40.0,
            remaining_units: 40.0,
        }],
        40.0,
        Some(monday),
    )
    .expect("a zero-length allocation does not block the schedule");
    assert_eq!(actual.queue_position, 0);
    assert_eq!(actual.estimated_calendar_days, 1);
    assert_eq!(actual.working_days, 1);
}

/// The refusal is comparable, and its message is its code.
///
/// Both halves come from the same place: `new CapacityError('insufficient_capacity')`
/// is constructed with no message argument, so `super(message ?? code)` makes the
/// message the code. A caller matching on `to_string()` therefore sees exactly
/// what a caller matching on the TypeScript error's `code` sees, which is what
/// makes the `err` field in the reference file a fair thing to compare against.
#[test]
fn the_refusal_is_comparable_and_its_message_is_its_code() {
    let error = CapacityError::insufficient_capacity();
    assert_eq!(error.to_string(), "insufficient_capacity");
    assert_eq!(error.code(), "insufficient_capacity");
    assert_eq!(
        error,
        CapacityError::insufficient_capacity(),
        "the refusal is a value, so two refusals compare equal"
    );
}

/// `countWorkingDays` floors to one, including for a span that is backwards.
///
/// The floor is `Math.max(1, count)` and it applies to a negative span as much
/// as an empty one — the loop body never runs either way, and the function must
/// not return `0`, which its callers would divide by.
#[test]
fn count_working_days_floors_to_one() {
    let monday = Instant::from_millis(days(day_of(2030, 1, 7)));
    let friday = Instant::from_millis(days(day_of(2030, 1, 11)));
    assert_eq!(count_working_days(monday, friday).expect("in-domain"), 4);
    assert_eq!(count_working_days(monday, monday).expect("in-domain"), 1);
    assert_eq!(count_working_days(friday, monday).expect("in-domain"), 1);

    // A span covering a weekend counts only the weekdays in it: Monday to the
    // following Monday is five working days, not seven.
    let next_monday = Instant::from_millis(days(day_of(2030, 1, 14)));
    assert_eq!(
        count_working_days(monday, next_monday).expect("in-domain"),
        5
    );
}

/// `nextBusinessDay` is a no-op on a weekday and a skip on a weekend, and the
/// skip zeroes the time-of-day only because it stepped over one.
///
/// This is the primitive the `offset-tz-negative` fixture depends on, stated
/// directly so a change to it fails here with the rule named rather than in the
/// differential loop with six fields to read.
#[test]
fn next_business_day_preserves_a_weekday_and_skips_a_weekend() {
    // 2030-01-07 is a Monday, at 05:00 UTC.
    let monday_at_five = Instant::from_millis(days(day_of(2030, 1, 7)) + 5 * 3_600_000);
    assert_eq!(
        next_business_day(monday_at_five)
            .expect("a Monday is in-domain")
            .as_millis(),
        monday_at_five.as_millis(),
        "a weekday is returned unchanged, time-of-day and all"
    );

    // Saturday and Sunday both step to Monday at midnight.
    let saturday = Instant::from_millis(days(day_of(2030, 1, 12)));
    let sunday = Instant::from_millis(days(day_of(2030, 1, 13)));
    let monday = Instant::from_millis(days(day_of(2030, 1, 14)));
    assert_eq!(
        next_business_day(saturday)
            .expect("a Saturday is in-domain")
            .as_millis(),
        monday.as_millis()
    );
    assert_eq!(
        next_business_day(sunday)
            .expect("a Sunday is in-domain")
            .as_millis(),
        monday.as_millis()
    );

    // And a weekday with a time-of-day keeps it, which is the whole subtlety:
    // `setUTCHours(0, 0, 0, 0)` runs inside the weekend loop only.
    assert!(
        !next_business_day(monday_at_five)
            .expect("a Monday is in-domain")
            .is_weekend(),
        "the skip lands on a working day"
    );
}

/// RA07's end-to-end guarantee at the public entrypoints: the extreme inputs
/// that used to hang `count_working_days` forever are refused with the stable
/// wire code, and a valid wide-but-supported span still walks.
///
/// The hang was `while current < finish` over a `plus_days` that returned the
/// unchanged instant on overflow. Both endpoints here are `i64::MAX`-scale,
/// far outside the supported [`Instant`] domain, so the refusal happens before
/// the loop is ever entered.
#[test]
fn extreme_calendar_inputs_are_refused_with_invalid_request_not_a_hang() {
    let start = Instant::from_millis(i64::MAX - 1);
    let finish = Instant::from_millis(i64::MAX);

    // The pure primitive: a typed, immediate error.
    let error = count_working_days(start, finish).expect_err("out-of-domain must not walk");
    assert!(matches!(
        error,
        archava_capacity::CalendarError::TimestampOutOfRange { .. }
    ));

    // And through `calculate_schedule`, which is the surface callers use: the
    // same refusal reaches them as the baseline's `invalid_request` code.
    let error = calculate_schedule(
        PoolCapacity {
            weekly_capacity: 100.0,
            max_concurrent_jobs: 2,
        },
        &[ActiveAllocation {
            id: "extreme".to_string(),
            start,
            finish,
            required_units: 10.0,
            remaining_units: 10.0,
        }],
        10.0,
        Some(start),
    )
    .expect_err("an out-of-domain allocation span must be refused");
    assert_eq!(error.code(), "invalid_request");

    // A valid, wide-but-supported allocation inside the horizon still
    // schedules — the bound refuses pathology, not real work.
    let monday = Instant::from_millis(days(day_of(2030, 1, 7)));
    let one_year = Instant::from_millis(days(day_of(2031, 1, 7)));
    assert_eq!(
        count_working_days(monday, one_year).expect("supported"),
        261
    );
}

/// A span beyond the horizon refuses before the first walk step, typed and
/// through the caller's surface.
///
/// `MAX_HORIZON_DAYS` is calendar.rs's termination guarantee: a walk over a
/// bounded span is finite by construction, so a span past the bound is a
/// malformed request, not a loop to time out. The witness pins both layers —
/// the primitive's named [`CalendarError::HorizonExceeded`] variant, and the
/// `invalid_request` code the surface callers see — plus the immediacy
/// property the mandate's "no hang" wording implies: the refusal is checked
/// *before* any step, so refusing does not follow from the cap at all.
///
/// Boundary detail worth keeping: `MAX_HORIZON_DAYS + 1` days is the FIRST
/// span that must refuse; a span of exactly the horizon must still answer, so
/// the boundary is pinned on both sides rather than only the refusal side.
#[test]
fn a_span_beyond_the_horizon_is_refused_before_the_walk() {
    let monday = Instant::from_millis(days(day_of(2030, 1, 7)));

    // The primitive: one day past the horizon, named variant, exact span read.
    let beyond = Instant::from_millis(
        monday
            .as_millis()
            .checked_add(days(archava_capacity::MAX_HORIZON_DAYS + 1))
            .expect("a horizon-plus-one span fits in the domain"),
    );
    let error = count_working_days(monday, beyond).expect_err("a beyond-horizon span must refuse");
    let span_days = archava_capacity::MAX_HORIZON_DAYS + 1;
    assert!(
        matches!(error, archava_capacity::CalendarError::HorizonExceeded { days } if days == span_days),
        "expected HorizonExceeded({span_days}), got {error:?}"
    );

    // The surface: the same span through calculate_schedule leaves callers
    // with the one code the baseline vocabulary has for it.
    let surface_error = calculate_schedule(
        PoolCapacity {
            weekly_capacity: 100.0,
            max_concurrent_jobs: 2,
        },
        &[ActiveAllocation {
            id: "beyond-horizon".to_string(),
            start: monday,
            finish: beyond,
            required_units: 10.0,
            remaining_units: 10.0,
        }],
        10.0,
        Some(monday),
    )
    .expect_err("a beyond-horizon allocation must be refused at the surface");
    assert_eq!(surface_error.code(), "invalid_request");

    // The boundary's other side: a span of exactly `MAX_HORIZON_DAYS` is
    // inside the supported horizon and still answers — refusing is what this
    // line must never see.
    let at_horizon = Instant::from_millis(
        monday
            .as_millis()
            .checked_add(days(archava_capacity::MAX_HORIZON_DAYS))
            .expect("an exact-horizon span fits in the domain"),
    );
    count_working_days(monday, at_horizon).expect("an exact-horizon span is supported");
}

/// The search loop is bounded by the iteration cap and *advances* — both
/// directions named here because "bounded" alone is satisfied by a loop that
/// never makes progress either.
///
/// The cap is `MAX_ITERATIONS == 1000` (pinned literal; see
/// `the_two_literals_are_the_baselines_literals`). What this witness adds over
/// the recorded fixture rows is the shape of the two ends:
///
/// - a pool that can never service the job (`maxConcurrentJobs: 0`) walks the
///   search to its recorded end — the `unsatisfiable-concurrency` refusal —
///   instead of a hang;
/// - a job far bigger than one week's burn still *advances* to its answer
///   (the recorded `longest-horizon-2000h` row: 2000 units at 40/day = 50
///   working days scheduled from the desired Monday).
#[test]
fn the_capped_loop_refuses_the_unsatisfiable_and_advances_to_schedule() {
    let monday = Instant::from_millis(days(day_of(2030, 1, 7)));

    // Advance: the 2000-unit, 40-per-day job lands on 2030-03-18 per the
    // recorded row — 50 working days after the start Monday.
    let scheduled = calculate_schedule(
        PoolCapacity {
            weekly_capacity: 200.0,
            max_concurrent_jobs: 1,
        },
        &[],
        2000.0,
        Some(monday),
    )
    .expect("a big-but-satisfiable job must schedule by advancing");
    assert_eq!(scheduled.queue_position, 0);
    assert_eq!(
        scheduled.scheduled_start.as_millis(),
        days(day_of(2030, 1, 7)),
        "nothing blocks it, so it starts on its desired Monday"
    );
    assert_eq!(
        scheduled.scheduled_finish.as_millis(),
        days(day_of(2030, 3, 18)),
        "2000 units at 40/day is 50 working days ≈ 10 weeks + 1 day"
    );
    assert_eq!(scheduled.working_days, 50);
    assert_eq!(scheduled.burn_rate_per_day, 40.0);

    // Bounded refusal: a pool with no concurrency rejects every day (0 + 1 >
    // 0), the loop advances one day per iteration because nothing is ahead to
    // jump to, and the cap turns a permanently saturated search into the
    // baseline's own `insufficient_capacity`.
    let unsatisfiable = calculate_schedule(
        PoolCapacity {
            weekly_capacity: 200.0,
            max_concurrent_jobs: 0,
        },
        &[],
        40.0,
        Some(monday),
    )
    .expect_err("a pool with no concurrency can never service a job");
    assert_eq!(
        unsatisfiable.code(),
        "insufficient_capacity",
        "the recorded unsatisfiable-concurrency refusal"
    );
}
